// src/pages/Landing.tsx
// public front door: what fokus is, a live demo of a path building itself,
// and the real product on screen. shown to signed-out visitors at "/".

import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import OfflineNotice from "../components/OfflineNotice";
import dashboardShot from "../assets/shots/dashboard.png";
import roadmapShot from "../assets/shots/roadmap.png";
import moduleShot from "../assets/shots/module.png";

// real roadmaps generated by the app, used for the live path demo
const DEMOS = [
  {
    topic: "origami",
    done: 3,
    modules: [
      "Paper selection basics",
      "Fundamental crease techniques",
      "Single-fold models introduction",
      "Symmetric folding principles",
      "Complex base development",
      "Dynamic transformations mastery",
      "Three-dimensional sculpting",
      "Material exploration & innovation",
    ],
  },
  {
    topic: "machine learning",
    done: 2,
    modules: [
      "Foundations of machine learning",
      "Supervised learning deep dive",
      "Unsupervised learning & EDA",
      "Recurrent neural networks basics",
      "Attention mechanism fundamentals",
      "Transformer architecture mastery",
      "Quantum machine learning overview",
      "Advanced topics & research",
    ],
  },
  {
    topic: "cooking",
    done: 3,
    modules: [
      "Foundations of kitchen safety",
      "Essential kitchen tools & prep",
      "Basic cooking techniques",
      "Ingredient knowledge & seasoning",
      "Intermediate flavor building",
      "Advanced baking & pastry",
      "International cuisine mastery",
      "Professional kitchen management",
    ],
  },
];

// one tick every 160ms. each topic: reveal cells, check some off, hold, move on
const CYCLE = 34;
const SHOW_AT = 1;   // tick when modules start appearing
const CHECK_AT = 9;  // tick when the first module gets checked

const PathDemo = () => {
  // honour reduced motion: skip the animation and show a finished path
  const reduced = typeof window !== "undefined"
    && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const [tick, setTick] = useState(0);

  useEffect(() => {
    if (reduced) return;
    const id = setInterval(() => setTick((t) => t + 1), 160);
    return () => clearInterval(id);
  }, [reduced]);

  const demo = reduced ? DEMOS[0] : DEMOS[Math.floor(tick / CYCLE) % DEMOS.length];
  const local = reduced ? CYCLE : tick % CYCLE;
  const total = demo.modules.length;
  const shown = reduced ? total : Math.max(0, Math.min(total, local - SHOW_AT + (local >= SHOW_AT ? 1 : 0)));
  const checked = reduced ? demo.done : Math.max(0, Math.min(demo.done, local - CHECK_AT));

  return (
    <div className="lp-demo" aria-label="A path building itself, module by module">
      <div className="lp-demo-head">
        <span className="lp-demo-input" aria-hidden="true">
          {demo.topic}
        </span>
        <span className="lp-demo-go" aria-hidden="true">New roadmap</span>
      </div>
      <div className="lp-demo-rail">
        {demo.modules.map((title, i) => (
          <div
            key={`${demo.topic}-${i}`}
            className={`lp-cell ${i < shown ? "in" : ""} ${i < checked ? "done" : ""} cell-lp-${(i % 8) + 1}`}
            style={{ transitionDelay: `${i * 20}ms` }}
          >
            <span className="lp-cell-step">
              {i < checked ? "✓" : String(i + 1).padStart(2, "0")}
            </span>
            <span className="lp-cell-name">{title}</span>
          </div>
        ))}
      </div>
      <p className="lp-demo-status" aria-live="off">
        {shown < total
          ? "Building your path, one module at a time"
          : checked > 0
            ? `${checked} of ${total} modules done`
            : "Your path is ready. Open module 1."}
      </p>
    </div>
  );
};

const Landing = () => (
  <div className="lp">
    <OfflineNotice />
    <nav className="lp-nav">
      <span className="lp-wordmark"><span className="lp-f">F</span><span className="lp-name">FOKUS</span></span>
      <span className="lp-nav-links">
        <Link className="lp-btn lp-btn-ghost" to="/login">Sign in</Link>
        <Link className="lp-btn lp-btn-primary" to="/login?tab=register">Create account</Link>
      </span>
    </nav>

    <header className="lp-hero">
      <div className="lp-hero-inner">
        <div className="lp-strip" aria-hidden="true">
          {Array.from({ length: 8 }, (_, i) => (
            <span key={i} className={`lp-strip-cell cell-lp-${i + 1}`} style={{ animationDelay: `${i * 70}ms` }} />
          ))}
        </div>
        <h1 className="lp-h1">Type any topic.<br />Get a learning path made for you.</h1>
        <p className="lp-sub">
          FOKUS builds a dynamic module-by-module path for whatever you want to learn,
          with a tutor-written guide, real videos, and real courses in every step.
        </p>
        <div className="lp-ctas">
          <Link className="lp-btn lp-btn-primary" to="/login?tab=register">Create account</Link>
          <Link className="lp-btn lp-btn-ghost" to="/login">Sign in</Link>
        </div>
      </div>
      <div className="lp-window lp-hero-window">
        <div className="lp-window-bar" aria-hidden="true">
          <span className="lp-dot" /><span className="lp-dot" /><span className="lp-dot" />
          <span className="lp-url">fokus.app</span>
        </div>
        <img src={dashboardShot} alt="The FOKUS dashboard with a Continue learning card and an 8-segment roadmap progress bar" />
      </div>
    </header>

    <section className="lp-section">
      <div className="lp-section-head">
        <h2>Watch your path build itself</h2>
        <p>A topic goes in, a path sized to it comes out: each module building on the last.</p>
      </div>
      <PathDemo />
    </section>

    <section className="lp-section lp-steps-section">
      <div className="lp-steps">
        <div className="lp-step">
          <span className="lp-step-n">1</span>
          <h3>Name a topic</h3>
          <p>Anything you want to learn, from origami to machine learning.</p>
        </div>
        <div className="lp-step">
          <span className="lp-step-n">2</span>
          <h3>The AI builds your path</h3>
          <p>It researches real sources, then writes a dynamic module-by-module path in seconds.</p>
        </div>
        <div className="lp-step">
          <span className="lp-step-n">3</span>
          <h3>Open a module and learn</h3>
          <p>Each module opens into a tutor guide with handpicked videos and course links.</p>
        </div>
      </div>
    </section>

    <section className="lp-section">
      <div className="lp-section-head">
        <h2>A path you can actually see</h2>
        <p>Every roadmap is a timeline. Check off modules and watch the rail fill.</p>
      </div>
      <div className="lp-pair">
        <figure className="lp-fig">
          <div className="lp-window">
            <div className="lp-window-bar" aria-hidden="true">
              <span className="lp-dot" /><span className="lp-dot" /><span className="lp-dot" />
              <span className="lp-url">fokus.app/roadmap</span>
            </div>
            <img src={roadmapShot} alt="A watercolor painting roadmap shown as a vertical timeline of numbered modules" />
          </div>
          <figcaption>Your roadmap, one module per step</figcaption>
        </figure>
        <figure className="lp-fig">
          <div className="lp-window">
            <div className="lp-window-bar" aria-hidden="true">
              <span className="lp-dot" /><span className="lp-dot" /><span className="lp-dot" />
              <span className="lp-url">fokus.app/roadmap/1/m/2</span>
            </div>
            <img src={moduleShot} alt="A module page with a study guide, video recommendations, and course links" />
          </div>
          <figcaption>Study guide, videos, and courses in one page</figcaption>
        </figure>
      </div>
    </section>

    <section className="lp-section lp-band">
      <div className="lp-band-inner">
        <div>
          <h2>Progress that sticks</h2>
          <p>Your roadmaps are saved to your account, so the path is there when you come back.</p>
          <ul className="lp-points">
            <li>Check off modules as you finish them</li>
            <li>Pick up exactly where you left off</li>
            <li>Watch your streak in the activity grid</li>
          </ul>
        </div>
        <div className="lp-window">
          <div className="lp-window-bar" aria-hidden="true">
            <span className="lp-dot" /><span className="lp-dot" /><span className="lp-dot" />
            <span className="lp-url">fokus.app</span>
          </div>
          <img src={dashboardShot} alt="Saved roadmaps with progress bars and an activity grid in the sidebar" />
        </div>
      </div>
    </section>

    <section className="lp-cta-band">
      <h2>Start your first roadmap.</h2>
      <p>Type a topic, and your path is seconds away.</p>
      <Link className="lp-btn lp-btn-primary" to="/login?tab=register">Create account</Link>
    </section>

    <footer className="lp-footer">
      <span className="lp-wordmark"><span className="lp-f">F</span><span className="lp-name">FOKUS</span></span>
      <p>Made for people who like a plan.</p>
      <Link className="lp-btn lp-btn-ghost" to="/login">Sign in</Link>
    </footer>
  </div>
);

export default Landing;
